import React, { useState, useMemo } from "react";

import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";

import { useCart } from "react-use-cart";

import products from "../products/Products";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */

const CATEGORIES = [
  { id: "All", label: "All", icon: Sparkles },
  { id: "Rings", label: "Rings", icon: Gem },
  { id: "Necklaces", label: "Necklaces", icon: Sparkles },
  { id: "Bracelets", label: "Bracelets", icon: CircleDot },
  { id: "Earrings", label: "Earrings", icon: Star },
  { id: "Chains", label: "Chains", icon: Link2 },
  { id: "Watches", label: "Watches", icon: Watch },
];

const CATEGORY_ICON = {
  Rings: Gem,
  Necklaces: Sparkles,
  Bracelets: CircleDot,
  Earrings: Star,
  Chains: Link2,
  Watches: Watch,
};

/* ============================================================
   FOOTER
   ============================================================ */

function PlaceholderFooter() {
  return (
    <footer className="lux-footer">
      <div className="lux-footer-inner">

        <div className="lux-footer-col lux-footer-brand">

          <div className="lux-logo lux-logo-footer">
            MAISON&nbsp;&amp;&nbsp;LUXE
          </div>

          <p>
            Fine accessories, crafted with intention.
            Timeless pieces for every story.
          </p>

          <div className="lux-footer-social">

            <a href="#" aria-label="Instagram">
              <FaInstagram size={16} />
            </a>

            <a href="#" aria-label="Facebook">
              <FaFacebookF size={16} />
            </a>

            <a href="#" aria-label="Twitter">
              <FaTwitter size={16} />
            </a>

          </div>
        </div>

        <div className="lux-footer-col">

          <h4>Shop</h4>

          <a href="#">Rings</a>
          <a href="#">Necklaces</a>
          <a href="#">Watches</a>

        </div>

        <div className="lux-footer-col">

          <h4>Support</h4>

          <a href="#">Shipping</a>
          <a href="#">Returns</a>
          <a href="#">Contact Us</a>

        </div>

        <div className="lux-footer-col">

          <h4>Newsletter</h4>

          <p>
            Be first to know about new arrivals.
          </p>

          <div className="lux-footer-form">

            <input
              type="email"
              placeholder="Your email"
            />

            <button type="button">
              Join
            </button>

          </div>

        </div>

      </div>

      <div className="lux-footer-bottom">

        © {new Date().getFullYear()} Maison &amp; Luxe.
        All rights reserved.

      </div>
    </footer>
  );
}

/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {

  const { addItem } = useCart();

  const Icon = product.icon;

  const [imgFailed, setImgFailed] = useState(false);

  const showImage =
    product.image && !imgFailed;

  const handleAddToCart = () => {

    addItem({
      id: product.id,
      title: product.name,
      price: product.price,
      images: product.image
        ? [product.image]
        : [],
    });

    alert("Product added to cart successfully!");
  };

  return (
    <article className="lux-card">

      <div className="lux-card-media">

        {/* PRODUCT IMAGE */}

        {showImage ? (

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-image-link"
          >

            <img
              src={product.image}
              alt={product.name}
              className="lux-card-img"
              loading="lazy"
              onError={() => setImgFailed(true)}
            />

          </Link>

        ) : (

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-media-icon"
          >

            <Icon
              size={40}
              strokeWidth={1}
            />

          </Link>

        )}

        {/* BADGE */}

        {product.badge && (

          <span className="lux-card-badge">
            {product.badge}
          </span>

        )}

        {/* QUICK ADD */}

        <button
          type="button"
          className="lux-card-quickadd"
          aria-label={`Add ${product.name} to cart`}
          onClick={handleAddToCart}
        >

          <ShoppingBag
            size={16}
            strokeWidth={1.5}
          />

        </button>

      </div>

      {/* CARD BODY */}

      <div className="lux-card-body">

        <span className="lux-card-eyebrow">
          {product.category}
        </span>

        <h3 className="lux-card-name">
          {product.name}
        </h3>

        <div className="lux-card-price">
          ${product.price.toFixed(2)}
        </div>

        <div className="lux-card-actions">

          {/* VIEW DETAILS */}

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-btn lux-btn-outline"
          >
            View Details
          </Link>

          {/* ADD TO CART */}

          <button
            type="button"
            className="lux-btn lux-btn-solid"
            onClick={handleAddToCart}
          >
            Add to Cart
          </button>

        </div>

      </div>

    </article>
  );
}

/* ============================================================
   ALL CART
   ============================================================ */

function AllCart() {

  const [selectedCategory, setSelectedCategory] =
    useState("All");

  /*
    نفس products الأصلية الموجودة في:
    ../products/Products
  */

  const filteredProducts = useMemo(() => {

    if (!Array.isArray(products)) {
      return [];
    }

    if (selectedCategory === "All") {
      return products;
    }

    return products.filter(
      (product) =>
        product.category === selectedCategory
    );

  }, [selectedCategory]);

  return (
    <>

      <style>
        {fontImport}
      </style>

      <main className="lux-page">

        {/* ====================================================
            HERO
        ==================================================== */}

        <section className="lux-collections-hero">

          <div className="lux-collections-hero-content">

            <span className="lux-hero-eyebrow">
              MAISON &amp; LUXE
            </span>

            <h1>
              All Products
            </h1>

            <p>
              Discover timeless pieces crafted to
              complement every moment and every story.
            </p>

          </div>

        </section>

        {/* ====================================================
            CATEGORIES
        ==================================================== */}

        <section className="lux-category-section">

          <div className="lux-category-list">

            {CATEGORIES.map((category) => {

              const Icon = category.icon;

              const isActive =
                selectedCategory === category.id;

              return (

                <button
                  key={category.id}
                  type="button"
                  className={
                    isActive
                      ? "lux-category-btn active"
                      : "lux-category-btn"
                  }
                  onClick={() =>
                    setSelectedCategory(category.id)
                  }
                >

                  <Icon
                    size={18}
                    strokeWidth={1.4}
                  />

                  <span>
                    {category.label}
                  </span>

                </button>

              );
            })}

          </div>

        </section>

        {/* ====================================================
            PRODUCTS
        ==================================================== */}

        <section className="lux-products-section">

          <div className="lux-products-header">

            <div>

              <span className="lux-products-eyebrow">
                COLLECTION
              </span>

              <h2>

                {selectedCategory === "All"
                  ? "All Pieces"
                  : selectedCategory}

              </h2>

            </div>

            <span className="lux-products-count">

              {filteredProducts.length}{" "}

              {filteredProducts.length === 1
                ? "piece"
                : "pieces"}

            </span>

          </div>

          {filteredProducts.length > 0 ? (

            <div className="lux-products-grid">

              {filteredProducts.map((product) => {

                /*
                  هنا فقط بنجهز الـdata بالشكل
                  اللي ProductCard محتاجه.

                  مفيش PRODUCTS array جديدة.
                  ومفيش duplicate للـproducts.
                */

                const cardProduct = {
                  id: product.id,
                  name: product.title,
                  category: product.category,
                  price: Number(product.price) || 0,
                  icon:
                    CATEGORY_ICON[product.category] ||
                    Sparkles,
                  badge: product.badge,
                  image: product.thumbnail,
                };

                return (
                  <ProductCard
                    key={product.id}
                    product={cardProduct}
                  />
                );
              })}

            </div>

          ) : (

            <div className="lux-empty-products">

              <Sparkles
                size={42}
                strokeWidth={1}
              />

              <h3>
                No products found
              </h3>

              <p>
                There are currently no products
                in this collection.
              </p>

              <button
                type="button"
                className="lux-btn lux-btn-solid"
                onClick={() =>
                  setSelectedCategory("All")
                }
              >
                View All Products
              </button>

            </div>

          )}

        </section>

        {/* ====================================================
            FOOTER
        ==================================================== */}

        <PlaceholderFooter />

      </main>

    </>
  );
}

/* ============================================================
   EXPORT
   ============================================================ */

export default AllCart;
